import{_ as e,o as a,c as n,a3 as o}from"./chunks/framework.B5WAEDB7.js";const u=JSON.parse('{"title":"Customizing the empty state","description":"Change the text that appears when a view shows no entries.","frontmatter":{"title":"Customizing the empty state","description":"Change the text that appears when a view shows no entries."},"headers":[],"relativePath":"en/ansichten/leerzustand.md","filePath":"en/ansichten/leerzustand.md","lastUpdated":1787319236000}'),r={name:"en/ansichten/leerzustand.md"};function i(s,t,d,h,l,p){return a(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="customizing-the-empty-state" tabindex="-1">Customizing the empty state <a class="header-anchor" href="#customizing-the-empty-state" aria-label="Permalink to &quot;Customizing the empty state&quot;">​</a></h1><p>If a view shows no entries, a notice text appears. By default it reads:</p><blockquote><p><strong>No results found</strong><em>Adjust the filters or create a new entry.</em></p></blockquote><p>Both parts can be changed.</p><h2 id="changing-it" tabindex="-1">Changing it <a class="header-anchor" href="#changing-it" aria-label="Permalink to &quot;Changing it&quot;">​</a></h2><p>Via <strong>More</strong> (⋮) → <strong>Edit empty view</strong>. You can edit:</p><table tabindex="0"><thead><tr><th>Field</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Title</strong></td><td>The heading</td></tr><tr><td><strong>Subtitle</strong></td><td>The explanatory text below it</td></tr></tbody></table><p>The setting applies <strong>per view</strong> — other views of the same Grid remain unaffected.</p><h2 id="when-it-s-worth-doing" tabindex="-1">When it&#39;s worth doing <a class="header-anchor" href="#when-it-s-worth-doing" aria-label="Permalink to &quot;When it&#39;s worth doing&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Especially in portals</p><p>&quot;No results found&quot; makes sense to you. To a customer opening a <a href="/en/seiten/portal-veroeffentlichen">portal</a>, it reads like an error.</p><p>Better: &quot;No bookings for this period yet.&quot; or &quot;Your requests will appear here once they&#39;ve been processed.&quot;</p></div><p>More cases:</p><table tabindex="0"><thead><tr><th>Situation</th><th>Possible text</th></tr></thead><tbody><tr><td>Task view, everything done</td><td><em>All done — nothing to do.</em></td></tr><tr><td>Filtered &quot;Overdue&quot; view</td><td><em>No overdue items.</em></td></tr><tr><td>New Grid, still being set up</td><td><em>No data yet. Create the first entry.</em></td></tr><tr><td>Portal for customers</td><td><em>As soon as documents are available, they&#39;ll appear here.</em></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">An empty state can be good news</p><p>In filtered views, &quot;no entries&quot; often means there&#39;s nothing to do. Phrase the text accordingly — that&#39;s more informative than a neutral &quot;nothing found.&quot;</p></div><h2 id="empty-doesn-t-always-mean-empty" tabindex="-1">Empty doesn&#39;t always mean empty <a class="header-anchor" href="#empty-doesn-t-always-mean-empty" aria-label="Permalink to &quot;Empty doesn&#39;t always mean empty&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Check the cause</p><p>An empty state can have several reasons:</p><table tabindex="0"><thead><tr><th>Cause</th><th>Recognizable by</th></tr></thead><tbody><tr><td>The Grid is genuinely empty</td><td>Unfiltered views are empty too</td></tr><tr><td>A <strong>filter</strong> is hiding everything</td><td>The filter button shows active conditions</td></tr><tr><td>A <strong>temporary filter</strong> is active</td><td>Only for you, disappears after the session</td></tr><tr><td>A <strong>search</strong> is narrowing things down</td><td>The search field has text in it</td></tr></tbody></table><p>Before adjusting the text, make sure the view is actually showing the right thing.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/ansichten/was-ist-eine-ansicht">What is a View</a></li><li><a href="/en/ansichten/filtern-sortieren-gruppieren">Filtering, Sorting, Grouping</a></li><li><a href="/en/seiten/portal-veroeffentlichen">Publishing a portal</a></li></ul>',17)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
